    try {
        const rows = db.prepare(`SELECT * FROM [${tname}] LIMIT 5`).all();
        const info = db.prepare(`PRAGMA table_info([${tname}])`).all();
        results[tname] = { cols: info.map(c => c.name), rows: rows };
    } catch(e) {
        results[tname] = { error: e.message };
    }
}

fs.writeFileSync('./db_full_dump.json', JSON.stringify(results, null, 2));
console.log('DISCOVERY_DONE');
db.close();
"""
